from pathlib import Path
import json,collections,hashlib
R=Path(__file__).resolve().parent;V=R.parent
def main():
 s=json.loads((R/'STATUS.json').read_text());r=json.loads((R/'REGISTRATION.json').read_text());review=json.loads((R/'REVIEW-COMBINED.json').read_text())
 lines=['PROSPECTIVE IN IMAGE VARIABLE ONLY — text events exposed (v100/v102).','Shared writing geometry and blind registration only; no picture ratings or scientific tests.','',s['status'],f"Visually reviewed source pages: {s['reviewed_pages']} / {s['ready_pages']}",f"Shared physical lines: {s['shared_physical_lines']} (original 45 retained unchanged)",f"H/F reading-specific registered blocks: {s['registered_reading_blocks']}",f"Excluded/pending reading units: {s['excluded_reading_units']}",f"Dropped physical visual blocks: {s['visual_dropped_blocks']}",'34 additional folios remain withheld for ambiguous/composite canvas registration.','', 'TIMING EXCEPTION: v4.2 was not frozen before initial registration. Retained source geometry is independently blind, but pre-registration timing is not certified. Original audit, receipts, failed extractors, drops and snapshots remain retained.','','Reading-unit exclusions/pending:']
 for reason,n in sorted(s['exclusions_by_reason'].items()):lines.append(f'  {reason}: {n}')
 lines+=['','Independent registrar provenance:']
 for role,src in review['sources'].items():lines.append(f"  {role}: {src['registrar_id']}; {src['saved_pages']} saved page reviews; input review SHA256 {src['sha256']}")
 lines+=['','All saved source-review drop versions are indexed in HISTORICAL-DROPPED-BLOCKS.csv and DROP-HISTORY-INDEX.json. Repeated regions across versions are not independent observations. Fourteen initially unfinished pages received a separate source-only fine-geometry pass. Primary B subsequently certified four of those during its own final QA; those primary boxes were retained, and the second review agreed on unit/count without replacing them. Six further fields acquired verified geometry from the follow-up. Remaining unresolved or uncompleted fine geometry remains unregistered, not an intrinsic negative manuscript result.']
 lines+=['','Registered source blocks (reading alternatives kept separate):']
 for row in r['accepted']:lines.append(f"  {row['folio']} {row['unit']} {row['reading']}: {row['line_count']} lines; {row['block_id']}; {row['registrar']}")
 lines+=['',f"Excluded/pending units actually present in EVT: {s.get('excluded_present_reading_units',s['excluded_reading_units'])}",f"Absent reading slots recorded separately: {s.get('absent_reading_slots',0)}",'Every excluded/pending reading unit and absent slot: DROPPED-BLOCKS.csv.','Every excluded reviewed physical visual block: VISUAL-DROPPED-BLOCKS.csv.','Accepted native rectangles: SHARED-LINE-GEOMETRY.json.','Separate H/F locus maps: REGISTRATION.json.','Review/checkpoint/correction provenance: REVIEW-COMBINED.json and worker records.','','Geometry limitation: conservative enclosing writing-row rectangles, sometimes overlapping for sloping writing/tall initials, not pixel-tight ink masks. Later distance-in-line-heights coding inherits this measurement definition; registration is not image-context validation.','','Scope: registration only. Raters remain blind. Picture ratings, labels, agreement, support, controls, outcomes joining and analysis remain held. v103 stays parked; no additional Rosettes leave-out grids.']
 (R/'REPORT.txt').write_text('\n'.join(lines)+'\n',encoding='utf-8')
 root=json.loads((V/'STATUS.json').read_text());root.update(registration=s['status'],registration_reviewed_pages=s['reviewed_pages'],shared_physical_lines=s['shared_physical_lines'],timing_exception_preserved=True,registration_permission='REGISTRATION ONLY; others remain held',registration_report='registration/REPORT.txt')
 if s['reviewed_pages']==s['ready_pages']:root['status']='SOURCE INSPECTION PASS COMPLETE; GEOMETRY PARTIAL; PICTURE RATING AND ANALYSIS HELD'
 (V/'STATUS.json').write_text(json.dumps(root,indent=2)+'\n',encoding='utf-8')
 names=['REPORT.txt','REGISTRATION.json','SHARED-LINE-GEOMETRY.json','DROPPED-BLOCKS.csv','VISUAL-DROPPED-BLOCKS.csv','STATUS.json','REVIEW-COMBINED.json']
 (R/'DELIVERY-HASHES.json').write_text(json.dumps({n:hashlib.sha256((R/n).read_bytes()).hexdigest() for n in names},indent=2)+'\n',encoding='utf-8')
 print(R/'REPORT.txt')
if __name__=='__main__':main()
